CREATE TRIGGER peg_followup_grant_update AFTER UPDATE ON peg_grants BEGIN
 INSERT OR IGNORE INTO peg_approval_followup_exclusions SELECT p.id,d.recipient_id,'access_changed' FROM peg_approval_followup_episodes p JOIN peg_approval_followup_events e ON e.episode_id=p.id JOIN peg_approval_followup_deliveries d ON d.event_id=e.id JOIN peg_approval_routes r ON r.id=p.route_id WHERE ((OLD.grantee_type='person' AND d.recipient_id=OLD.grantee_id) OR (OLD.grantee_type='team' AND d.recipient_id IN (SELECT grantee_id FROM peg_grants WHERE object_type='team' AND object_id=OLD.grantee_id AND grantee_type='person' AND revoked_at IS NULL)))
 AND ((OLD.object_type='task' AND OLD.object_id=r.task_id) OR EXISTS(SELECT 1 FROM peg_task_projects tp JOIN peg_projects pr ON pr.id=tp.project_id WHERE tp.task_id=r.task_id AND ((OLD.object_type='project' AND OLD.object_id=tp.project_id) OR (OLD.object_type='team' AND (pr.team_id=OLD.object_id OR EXISTS(SELECT 1 FROM peg_grants g WHERE g.object_type='project' AND g.object_id=pr.id AND g.grantee_type='team' AND g.grantee_id=OLD.object_id))))));
 UPDATE peg_approval_followup_deliveries SET state='cancelled',cause='access_changed',next_at=NULL WHERE id IN (SELECT d.id FROM peg_approval_followup_deliveries d JOIN peg_approval_followup_events e ON e.id=d.event_id JOIN peg_approval_followup_episodes p ON p.id=e.episode_id JOIN peg_approval_routes r ON r.id=p.route_id WHERE ((OLD.grantee_type='person' AND d.recipient_id=OLD.grantee_id) OR (OLD.grantee_type='team' AND d.recipient_id IN (SELECT grantee_id FROM peg_grants WHERE object_type='team' AND object_id=OLD.grantee_id AND grantee_type='person' AND revoked_at IS NULL)))
 AND ((OLD.object_type='task' AND OLD.object_id=r.task_id) OR EXISTS(SELECT 1 FROM peg_task_projects tp JOIN peg_projects pr ON pr.id=tp.project_id WHERE tp.task_id=r.task_id AND ((OLD.object_type='project' AND OLD.object_id=tp.project_id) OR (OLD.object_type='team' AND (pr.team_id=OLD.object_id OR EXISTS(SELECT 1 FROM peg_grants g WHERE g.object_type='project' AND g.object_id=pr.id AND g.grantee_type='team' AND g.grantee_id=OLD.object_id))))))) AND state IN ('queued','deferred','visible');
 END;
CREATE TRIGGER peg_followup_grant_delete AFTER DELETE ON peg_grants BEGIN
 INSERT OR IGNORE INTO peg_approval_followup_exclusions SELECT p.id,d.recipient_id,'access_changed' FROM peg_approval_followup_episodes p JOIN peg_approval_followup_events e ON e.episode_id=p.id JOIN peg_approval_followup_deliveries d ON d.event_id=e.id JOIN peg_approval_routes r ON r.id=p.route_id WHERE ((OLD.grantee_type='person' AND d.recipient_id=OLD.grantee_id) OR (OLD.grantee_type='team' AND d.recipient_id IN (SELECT grantee_id FROM peg_grants WHERE object_type='team' AND object_id=OLD.grantee_id AND grantee_type='person' AND revoked_at IS NULL)))
 AND ((OLD.object_type='task' AND OLD.object_id=r.task_id) OR EXISTS(SELECT 1 FROM peg_task_projects tp JOIN peg_projects pr ON pr.id=tp.project_id WHERE tp.task_id=r.task_id AND ((OLD.object_type='project' AND OLD.object_id=tp.project_id) OR (OLD.object_type='team' AND (pr.team_id=OLD.object_id OR EXISTS(SELECT 1 FROM peg_grants g WHERE g.object_type='project' AND g.object_id=pr.id AND g.grantee_type='team' AND g.grantee_id=OLD.object_id))))));
 UPDATE peg_approval_followup_deliveries SET state='cancelled',cause='access_changed',next_at=NULL WHERE id IN (SELECT d.id FROM peg_approval_followup_deliveries d JOIN peg_approval_followup_events e ON e.id=d.event_id JOIN peg_approval_followup_episodes p ON p.id=e.episode_id JOIN peg_approval_routes r ON r.id=p.route_id WHERE ((OLD.grantee_type='person' AND d.recipient_id=OLD.grantee_id) OR (OLD.grantee_type='team' AND d.recipient_id IN (SELECT grantee_id FROM peg_grants WHERE object_type='team' AND object_id=OLD.grantee_id AND grantee_type='person' AND revoked_at IS NULL)))
 AND ((OLD.object_type='task' AND OLD.object_id=r.task_id) OR EXISTS(SELECT 1 FROM peg_task_projects tp JOIN peg_projects pr ON pr.id=tp.project_id WHERE tp.task_id=r.task_id AND ((OLD.object_type='project' AND OLD.object_id=tp.project_id) OR (OLD.object_type='team' AND (pr.team_id=OLD.object_id OR EXISTS(SELECT 1 FROM peg_grants g WHERE g.object_type='project' AND g.object_id=pr.id AND g.grantee_type='team' AND g.grantee_id=OLD.object_id))))))) AND state IN ('queued','deferred','visible');
 END;
CREATE TRIGGER peg_followup_field_definition AFTER UPDATE ON peg_field_definitions BEGIN
 UPDATE peg_approval_routes SET followup_invalidated_at=CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) WHERE withdrawn_at IS NULL AND followup_invalidated_at IS NULL AND (task_id IN (SELECT task_id FROM peg_field_values WHERE field_id=NEW.id) OR task_id IN (SELECT tp.task_id FROM peg_task_projects tp JOIN peg_project_fields f ON f.project_id=tp.project_id WHERE f.field_id=NEW.id));
END;
CREATE TRIGGER peg_followup_tag_definition AFTER UPDATE ON peg_tags BEGIN
 UPDATE peg_approval_routes SET followup_invalidated_at=CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) WHERE withdrawn_at IS NULL AND followup_invalidated_at IS NULL AND task_id IN (SELECT task_id FROM peg_task_tags WHERE tag_id=NEW.id);
END;
CREATE TRIGGER peg_followup_workspace_update AFTER UPDATE ON peg_workspace_members WHEN NEW.role<>OLD.role BEGIN
 INSERT OR IGNORE INTO peg_approval_followup_exclusions SELECT p.id,OLD.operator_id,'membership_changed' FROM peg_approval_followup_episodes p WHERE p.workspace_id=OLD.workspace_id;
 UPDATE peg_approval_followup_deliveries SET state='cancelled',cause='membership_changed',next_at=NULL WHERE recipient_id=OLD.operator_id AND event_id IN (SELECT e.id FROM peg_approval_followup_events e JOIN peg_approval_followup_episodes p ON p.id=e.episode_id WHERE p.workspace_id=OLD.workspace_id) AND state IN ('queued','deferred','visible');
 UPDATE peg_approval_followup_episodes SET state='cancelled',cause='routing_authority_lost',next_at=NULL WHERE workspace_id=OLD.workspace_id AND state='active' AND route_id IN (SELECT id FROM peg_approval_routes WHERE created_by=OLD.operator_id);
END;
CREATE TRIGGER peg_followup_workspace_delete AFTER DELETE ON peg_workspace_members BEGIN
 INSERT OR IGNORE INTO peg_approval_followup_exclusions SELECT p.id,OLD.operator_id,'membership_changed' FROM peg_approval_followup_episodes p WHERE p.workspace_id=OLD.workspace_id;
 UPDATE peg_approval_followup_deliveries SET state='cancelled',cause='membership_changed',next_at=NULL WHERE recipient_id=OLD.operator_id AND event_id IN (SELECT e.id FROM peg_approval_followup_events e JOIN peg_approval_followup_episodes p ON p.id=e.episode_id WHERE p.workspace_id=OLD.workspace_id) AND state IN ('queued','deferred','visible');
 UPDATE peg_approval_followup_episodes SET state='cancelled',cause='routing_authority_lost',next_at=NULL WHERE workspace_id=OLD.workspace_id AND state='active' AND route_id IN (SELECT id FROM peg_approval_routes WHERE created_by=OLD.operator_id);
END;
